// Used by scorers like prefix-affinity that track routing history.
type observerFunc func(req *Request, targetInstance string)

// WeightedScoring routes requests using a composable scorer pipeline.
//
// Each scorer evaluates all instances on a [0,1] scale. Scores are combined
// with configurable weights: composite = Σ clamp(s_i) × w_i, then argmax.
//
// Available scorers: prefix-affinity (proportional prefix match ratio),
// queue-depth (min-max normalization of EffectiveLoad),
// kv-utilization (1 - KVUtilization), load-balance (1/(1 + EffectiveLoad)).
// See sim/routing_scorers.go and sim/routing_prefix_scorer.go for implementations.
//
// Stateful scorers (prefix-affinity) register observers that update internal
// state after each routing decision. Observers are called after argmax selection.
//
// Higher scores are preferred. Ties broken by first occurrence in snapshot order.
type WeightedScoring struct {
	scorers   []scorerFunc
	weights   []float64 // normalized to sum to 1.0
	observers []observerFunc
}

// Route implements RoutingPolicy for WeightedScoring.
func (ws *WeightedScoring) Route(req *Request, state *RouterState) RoutingDecision {
	snapshots := state.Snapshots
	if len(snapshots) == 0 {
		panic("WeightedScoring.Route: empty snapshots")
	}

	// EVOLVE-BLOCK-START
	// HYPOTHESIS-1: Adapting prefix-affinity weight by input length reduces cache_warmup latency by avoiding load imbalance for short-prefix requests
	// MECHANISM-1: Short inputs have minimal cache savings but prefix-affinity creates hot spots; reducing its weight for short inputs lets load-balance distribute evenly
	// EXPECT-1: cache_warmup_e2e_ms < 5000

	// HYPOTHESIS-2: Adding overload penalties prevents hot-spotting in load_spikes workload where a dominant prefix group overwhelms one instance
	// MECHANISM-2: When an instance's effective load exceeds the cluster average significantly, a multiplicative penalty reduces its score regardless of cache affinity
	// EXPECT-2: load_spikes_e2e_ms < 3000

	// HYPOTHESIS-3: Preserving high prefix-affinity weight for long-input sessions maintains multiturn performance while improving other workloads
	// MECHANISM-3: Long prefixes (multiturn) have substantial recomputation cost; keeping affinity weight high for len(InputTokens)>64 preserves cache hits
	// EXPECT-3: multiturn_e2e_ms < 200

	// Step 1: Compute per-scorer raw scores
	rawScores := make([]map[string]float64, len(ws.scorers))
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		rawScores[i] = make(map[string]float64, len(snapshots))
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			rawScores[i][snap.ID] = s
		}
	}

	// Step 2: Determine adaptive weights based on input length and SLO class
	inputLen := len(req.InputTokens)
	adaptiveWeights := make([]float64, len(ws.weights))
	copy(adaptiveWeights, ws.weights)

	// Baseline has 2 scorers: [0]=prefix-affinity, [1]=load-balance (each weight 0.5 after normalization)
	// Adapt: short inputs → favor load-balance; long inputs → favor prefix-affinity
	if len(adaptiveWeights) >= 2 {
		if inputLen <= 32 {
			// Very short: almost pure load-balance
			adaptiveWeights[0] = 0.05 // prefix-affinity
			adaptiveWeights[1] = 0.95 // load-balance
		} else if inputLen <= 64 {
			// Medium-short: moderate blend
			adaptiveWeights[0] = 0.25
			adaptiveWeights[1] = 0.75
		} else if inputLen <= 256 {
			// Medium: balanced with slight prefix preference
			adaptiveWeights[0] = 0.55
			adaptiveWeights[1] = 0.45
		} else {
			// Long prefix (multiturn sessions): strong cache affinity
			adaptiveWeights[0] = 0.75
			adaptiveWeights[1] = 0.25
		}

		// SLO-based adjustment: realtime requests are latency-sensitive, favor load-balance more
		if req.SLOClass == "realtime" {
			adaptiveWeights[0] *= 0.4
			adaptiveWeights[1] *= 1.6
		} else if req.SLOClass == "batch" {
			// Batch can tolerate queuing, slightly more cache affinity
			adaptiveWeights[0] *= 1.2
			adaptiveWeights[1] *= 0.8
		}
	}

	// Step 3: Compute weighted composite scores
	scores := make(map[string]float64, len(snapshots))
	for i := range ws.scorers {
		for _, snap := range snapshots {
			scores[snap.ID] += rawScores[i][snap.ID] * adaptiveWeights[i]
