		el := float64(snap.EffectiveLoad())
		// Progressive penalty when load exceeds average
		if avgLoad > 0 && el > avgLoad*1.3 {
			overloadRatio := el / avgLoad
			// Penalty grows with how far above average: 0.8 at 1.5x, 0.5 at 2x, etc.
			penalty := 1.0 / overloadRatio
			if penalty < 0.1 {
				penalty = 0.1
			}
			scores[snap.ID] *= penalty
		}
